const ai = $input.first().json;
const original = $('Normalize Ticket Data').first().json;

const text = ai.content.parts[0].text;
const parsed = JSON.parse(text);

return [
  {
    json: {
      ...original,
      intent: parsed.intent,
      department: parsed.department,
      sentiment: parsed.sentiment,
      urgency: parsed.urgency,
      confidence: parsed.confidence,
      escalation_required: parsed.escalation_required,
      reasoning_summary: parsed.reasoning_summary,
      missing_information: Array.isArray(parsed.missing_information)
        ? parsed.missing_information.join(", ")
        : parsed.missing_information
    }
  }
];

const ticket = $('Parse Gemini Classification').first().json;
const kbRows = $input.all().map(item => item.json);

const message = `${ticket.raw_message} ${ticket.intent} ${ticket.department}`.toLowerCase();

const scored = kbRows.map(row => {
  const keywords = String(row.keywords || "")
    .toLowerCase()
    .split(",")
    .map(k => k.trim())
    .filter(Boolean);

  const score = keywords.reduce((count, keyword) => {
    return message.includes(keyword) ? count + 1 : count;
  }, 0);

  return { ...row, match_score: score };
});

const matches = scored
  .filter(row => row.match_score > 0)
  .sort((a, b) => b.match_score - a.match_score)
  .slice(0, 3);

return [
  {
    json: {
      ...ticket,
      knowledge_base_matches: matches.length
        ? matches.map(row =>
            `${row.article_id}: ${row.topic}\nAnswer: ${row.answer}\nEscalation rule: ${row.escalation_rule}`
          ).join("\n\n")
        : "No relevant knowledge base article found."
    }
  }
];

