const text = ai.content.parts[0].text;
const parsed = JSON.parse(text);

return [
  {
    json: {
      ...ticket,
      reply_subject: parsed.reply_subject,
      draft_reply: parsed.reply_body,
      used_knowledge_base_ids: Array.isArray(parsed.used_knowledge_base_ids)
        ? parsed.used_knowledge_base_ids.join(", ")
        : parsed.used_knowledge_base_ids,
      reply_confidence: parsed.reply_confidence || parsed.confidence || "Not provided",
      needs_human_review: parsed.needs_human_review,
      internal_note: parsed.internal_note
    }
  }
];

